42	TemplateRowInputFormat::TemplateRowInputFormat(const Block & header_, std::unique_ptr<PeekableReadBuffer> buf_, const Params & params_,
43	                                               FormatSettings settings_, bool ignore_spaces_,
44	                                               ParsedTemplateFormatString format_, ParsedTemplateFormatString row_format_,
45	                                               std::string row_between_delimiter_)
46	    : RowInputFormatWithDiagnosticInfo(header_, *buf_, params_), buf(std::move(buf_)), data_types(header_.getDataTypes()),
47	      settings(std::move(settings_)), ignore_spaces(ignore_spaces_),
48	      format(std::move(format_)), row_format(std::move(row_format_)),
49	      default_csv_delimiter(settings.csv.delimiter), row_between_delimiter(row_between_delimiter_),
50	      format_reader(std::make_unique<TemplateFormatReader>(*buf, ignore_spaces_, format, row_format, row_between_delimiter, settings))
51	{
52	    /// Validate format string for rows
53	    std::vector<UInt8> column_in_format(header_.columns(), false);
54	    for (size_t i = 0; i < row_format.columnsCount(); ++i)
55	    {
56	        if (row_format.format_idx_to_column_idx[i])
57	        {
58	            if (header_.columns() <= *row_format.format_idx_to_column_idx[i])
59	                row_format.throwInvalidFormat("Column index " + std::to_string(*row_format.format_idx_to_column_idx[i]) +
60	                                              " must be less then number of columns (" + std::to_string(header_.columns()) + ")", i);
61	            if (row_format.escaping_rules[i] == EscapingRule::None)
62	                row_format.throwInvalidFormat("Column is not skipped, but deserialization type is None", i);
63	
64	            size_t col_idx = *row_format.format_idx_to_column_idx[i];
65	            if (column_in_format[col_idx])
66	                row_format.throwInvalidFormat("Duplicate column", i);
67	            column_in_format[col_idx] = true;
68	        }
69	    }
70	
71	    for (size_t i = 0; i < header_.columns(); ++i)
72	        if (!column_in_format[i])
73	            always_default_columns.push_back(i);
74	}
