81	bool TemplateRowInputFormat::readRow(MutableColumns & columns, RowReadExtension & extra)
82	{
83	    /// This function can be called again after it returned false
84	    if (unlikely(end_of_stream))
85	        return false;
86	
87	    if (unlikely(format_reader->checkForSuffix()))
88	    {
89	        end_of_stream = true;
90	        return false;
91	    }
92	
93	    updateDiagnosticInfo();
94	
95	    if (likely(row_num != 1))
96	        format_reader->skipRowBetweenDelimiter();
97	
98	    extra.read_columns.assign(columns.size(), false);
99	
100	    for (size_t i = 0; i < row_format.columnsCount(); ++i)
101	    {
102	        format_reader->skipDelimiter(i);
103	
104	        if (row_format.format_idx_to_column_idx[i])
105	        {
106	            size_t col_idx = *row_format.format_idx_to_column_idx[i];
107	            extra.read_columns[col_idx] = deserializeField(data_types[col_idx], serializations[col_idx], *columns[col_idx], i);
108	        }
109	        else
110	            format_reader->skipField(row_format.escaping_rules[i]);
111	    }
112	
113	    format_reader->skipRowEndDelimiter();
114	
115	    for (const auto & idx : always_default_columns)
116	        data_types[idx]->insertDefaultInto(*columns[idx]);
117	
118	    return true;
119	}
