172	template <bool is_header>
173	std::vector<String> CustomSeparatedFormatReader::readRowImpl()
174	{
175	    std::vector<String> values;
176	    skipRowStartDelimiter();
177	
178	    if (columns == 0)
179	    {
180	        do
181	        {
182	            values.push_back(readFieldIntoString<is_header>(values.empty()));
183	        } while (!checkEndOfRow());
184	        columns = values.size();
185	    }
186	    else
187	    {
188	        for (size_t i = 0; i != columns; ++i)
189	            values.push_back(readFieldIntoString<is_header>(i == 0));
190	    }
191	
