220	{
221	    skipSpaces();
222	    if (format_settings.custom.result_after_delimiter.empty())
223	    {
224	        if (!check_eof)
225	            return false;
226	
227	        return buf->eof();
228	    }
229	
230	    if (unlikely(checkString(format_settings.custom.result_after_delimiter, *buf)))
231	    {
232	        skipSpaces();
